use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.from_label(label: "ax");
    var bay = depot.locker.from_label(label: "bay");
    var cod = depot.locker.from_label(label: "cod");
    ax = depot.locker.stow(locker: ax, load: 12);
    ax = depot.locker.stow(locker: ax, load: 9);
    bay = depot.locker.stow(locker: bay, load: 30);
    bay = depot.locker.stow(locker: bay, load: 25);
    cod = depot.locker.stow(locker: cod, load: 5);
    [
        depot.locker.to_text(locker: ax),
        depot.locker.to_text(locker: bay),
        depot.locker.to_text(locker: cod),
    ].join(sep: ",")
}

